import{_ as t,a,o as r,a4 as s}from"./chunks/framework.-FZumj2l.js";const p=JSON.parse('{"title":"Search Terms","description":"","frontmatter":{"outline":false},"headers":[],"relativePath":"api/rest-api/admin/marketing/search-seo/search-terms/index.md","filePath":"api/rest-api/admin/marketing/search-seo/search-terms/index.md","lastUpdated":1783420618000}'),o={name:"api/rest-api/admin/marketing/search-seo/search-terms/index.md"};function n(d,e,i,c,h,m){return r(),a("div",null,e[0]||(e[0]=[s('<h1 id="search-terms" tabindex="-1">Search Terms <a class="header-anchor" href="#search-terms" aria-label="Permalink to &quot;Search Terms&quot;">​</a></h1><p>A <strong>search term</strong> is a phrase a shopper typed into the storefront search box, recorded automatically each time it is used. Each row tracks how many times the term was searched and how many products that search returned, so you can see what shoppers are looking for. It mirrors the admin <strong>Marketing → Search &amp; SEO → Search Terms</strong> screen.</p><h2 id="how-search-terms-work" tabindex="-1">How search terms work <a class="header-anchor" href="#how-search-terms-work" aria-label="Permalink to &quot;How search terms work&quot;">​</a></h2><p>Search terms are <strong>storefront-originated</strong> — there is no create endpoint. Every storefront search adds or updates a row, so the list reflects real shopper demand.</p><ul><li><strong><code>term</code></strong> — the text that was searched.</li><li><strong><code>results</code></strong> — how many products that search returned. Storefront-recorded and read-only — a low number on a high-<code>uses</code> term flags demand the catalog isn&#39;t meeting.</li><li><strong><code>uses</code></strong> — how many times the term was searched. Storefront-recorded and read-only. Sort by <code>uses</code> descending to surface the most popular searches.</li><li><strong><code>redirectUrl</code></strong> — an optional URL the storefront sends this query to instead of running a normal search (e.g. point &quot;sale&quot; straight at a landing page). This is the one targeting field admins set; <code>term</code> text can also be corrected.</li><li><strong><code>channel</code> / <code>locale</code></strong> — the channel and locale the term was recorded on. <code>channel</code> is a detail-only object (<code>{ id, code, name }</code>); it is <code>null</code> on list rows.</li></ul><p><strong>What admins can change.</strong> Only <code>term</code> and <code>redirect_url</code> are editable. The counts are owned by the storefront and never accepted on update. Terms can also be deleted individually or in bulk to clean up noise.</p><p><strong>Relation to other menus.</strong> Search terms reveal the words shoppers use and where the catalog falls short. <a href="/api/rest-api/admin/marketing/search-seo/search-synonyms/">Search Synonyms</a> act on that signal — grouping interchangeable words so a term with poor results still matches the right products.</p><h2 id="operations-in-this-menu" tabindex="-1">Operations in this menu <a class="header-anchor" href="#operations-in-this-menu" aria-label="Permalink to &quot;Operations in this menu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Endpoint</th></tr></thead><tbody><tr><td><a href="/api/rest-api/admin/marketing/search-seo/search-terms-list.html">List</a></td><td><code>GET /api/admin/marketing/search-terms</code></td></tr><tr><td><a href="/api/rest-api/admin/marketing/search-seo/search-terms-detail.html">Detail</a></td><td><code>GET /api/admin/marketing/search-terms/{id}</code></td></tr><tr><td><a href="/api/rest-api/admin/marketing/search-seo/search-terms-update.html">Update</a></td><td><code>PUT /api/admin/marketing/search-terms/{id}</code></td></tr><tr><td><a href="/api/rest-api/admin/marketing/search-seo/search-terms-delete.html">Delete</a></td><td><code>DELETE /api/admin/marketing/search-terms/{id}</code></td></tr><tr><td><a href="/api/rest-api/admin/marketing/search-seo/search-terms-mass-delete.html">Mass Delete</a></td><td><code>POST /api/admin/marketing/search-terms/mass-delete</code></td></tr></tbody></table><p>There is no create endpoint — search terms are recorded automatically by storefront searches.</p><p>All Search Terms endpoints require an admin Bearer token — see <a href="/api/rest-api/admin/authentication.html">Authentication</a>.</p>',11)]))}const g=t(o,[["render",n]]);export{p as __pageData,g as default};
